import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    A = int(input_data[0])
    B = int(input_data[1])
    R = int(input_data[2])
    G = int(input_data[3])

    if 2 * R <= A and 2 * R <= B and 360 % G == 0:
        print('S')
    else:
        print('N')

if __name__ == '__main__':
    main()
